      "svg": "<svg viewBox=\"0 0 1100 1100\" xmlns=\"http://www.w3.org/2000/svg\"><svg viewBox=\"0 0 1100 1100\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" font-size=\"36\" fill=\"#ffd700\" font-weight=\"bold\" text-anchor=\"middle\">Reading the Verbal Marker</text><text x=\"550\" y=\"115\" font-size=\"24\" fill=\"#888\" text-anchor=\"middle\">One phrase moves the deal, one ends it</text><rect x=\"120\" y=\"220\" width=\"860\" height=\"240\" rx=\"20\" fill=\"#10b981\" opacity=\"0.15\" stroke=\"#10b981\" stroke-width=\"3\"/><text x=\"160\" y=\"270\" font-size=\"28\" fill=\"#10b981\" font-weight=\"bold\" text-anchor=\"start\">Genuine Buy-In Sounds Like</text><text x=\"160\" y=\"320\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"start\">“That's right, that's the whole</text><text x=\"160\" y=\"370\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"start\">problem right there.”</text><rect x=\"120\" y=\"500\" width=\"860\" height=\"240\" rx=\"20\" fill=\"#888\" opacity=\"0.15\" stroke=\"#888\" stroke-width=\"3\"/><text x=\"160\" y=\"550\" font-size=\"28\" fill=\"#888\" font-weight=\"bold\" text-anchor=\"start\">Placation Sounds Like</text><text x=\"160\" y=\"600\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"start\">“You're right, I guess.”</text><text x=\"160\" y=\"650\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"start\">“Sure, whatever you say.”</text><text x=\"160\" y=\"700\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"start\">“Yeah, fine, let's move on.”</text><rect x=\"140\" y=\"800\" width=\"820\" height=\"90\" rx=\"45\" fill=\"#ffd700\" opacity=\"0.15\" stroke=\"#ffd700\" stroke-width=\"3\"/><text x=\"550\" y=\"853\" font-size=\"22\" fill=\"#ffd700\" font-weight=\"bold\" text-anchor=\"middle\">Confirmation of a mirrored reality beats agreement to end a topic</text></svg></svg>",
